def find_emails(user, sender=None, subject=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0235000" if __import__("os").path.isdir("./environment_mix/0235000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    t0 = time.time()
    status = "ok"

    # ---- validation ----
    if not isinstance(user, str) or not user.strip():
        status = "validation_error"
        # log before returning
        audit = _load("usage_log.json")
        if not isinstance(audit, list):
            audit = []
        audit.append(
            {
                "id": f"req_{len(audit)+1}",
                "endpoint": "find_emails",
                "timestamp": _now_iso(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "user": user if isinstance(user, str) else None,
            }
        )
        _save("usage_log.json", audit)
        return _err("VALIDATION_ERROR", "Missing or empty user email address.")

    if sender is not None and not isinstance(sender, str):
        status = "validation_error"
        audit = _load("usage_log.json")
        if not isinstance(audit, list):
            audit = []
        audit.append(
            {
                "id": f"req_{len(audit)+1}",
                "endpoint": "find_emails",
                "timestamp": _now_iso(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "user": user,
            }
        )
        _save("usage_log.json", audit)
        return _err("VALIDATION_ERROR", "sender must be a string when provided.")
    if subject is not None and not isinstance(subject, str):
        status = "validation_error"
        audit = _load("usage_log.json")
        if not isinstance(audit, list):
            audit = []
        audit.append(
            {
                "id": f"req_{len(audit)+1}",
                "endpoint": "find_emails",
                "timestamp": _now_iso(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "user": user,
            }
        )
        _save("usage_log.json", audit)
        return _err("VALIDATION_ERROR", "subject must be a string when provided.")

    sender_s = sender.strip() if isinstance(sender, str) else ""
    subject_s = subject.strip() if isinstance(subject, str) else ""
    if not sender_s and not subject_s:
        status = "validation_error"
        audit = _load("usage_log.json")
        if not isinstance(audit, list):
            audit = []
        audit.append(
            {
                "id": f"req_{len(audit)+1}",
                "endpoint": "find_emails",
                "timestamp": _now_iso(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "user": user,
            }
        )
        _save("usage_log.json", audit)
        return _err("VALIDATION_ERROR", "Provide at least one filter: sender and/or subject.")

    # ---- rate limit (simple, observable) ----
    audit = _load("usage_log.json")
    if not isinstance(audit, list):
        audit = []

    now = datetime.datetime.now(datetime.timezone.utc)
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in audit:
        ts = r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            continue
        if dt >= window_start:
            recent += 1
    # default local service limit
    if recent >= 120:
        status = "rate_limited"
        audit.append(
            {
                "id": f"req_{len(audit)+1}",
                "endpoint": "find_emails",
                "timestamp": _now_iso(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "user": user,
            }
        )
        _save("usage_log.json", audit)
        return _err("RATE_LIMIT", "Too many requests. Please retry later.", limit=120, window_seconds=60)

    # ---- auth resolution (ambient) ----
    # No explicit credentials exist in this schema; allow if mailbox exists.
    mailboxes = _load("mailboxes.json")
    mailbox = None

    if isinstance(mailboxes, dict):
        mailbox = mailboxes.get(user)
    elif isinstance(mailboxes, list):
        for row in mailboxes:
            if isinstance(row, dict) and row.get("user") == user:
                mailbox = row
                break

    if mailbox is None:
        status = "not_found"
        audit.append(
            {
                "id": f"req_{len(audit)+1}",
                "endpoint": "find_emails",
                "timestamp": _now_iso(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "user": user,
            }
        )
        _save("usage_log.json", audit)
        return _err("NOT_FOUND", "Mailbox does not exist for user.", user=user)

    # ---- search ----
    sender_l = sender_s.lower()
    subject_l = subject_s.lower()
    matches = []
    folder_counts = {}

    if isinstance(mailbox, dict):
        for folder_name, msgs in mailbox.items():
            if folder_name == "user":
                continue
            if not isinstance(msgs, list):
                continue
            folder_counts[folder_name] = len(msgs)
            for m in msgs:
                if not isinstance(m, dict):
                    continue
                frm = str(m.get("from", "") or "")
                subj = str(m.get("subject", "") or "")
                if sender_l and sender_l not in frm.lower():
                    continue
                if subject_l and subject_l not in subj.lower():
                    continue
                matches.append(m)

    status = "ok"
    audit.append(
        {
            "id": f"req_{len(audit)+1}",
            "endpoint": "find_emails",
            "timestamp": _now_iso(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "user": user,
            "filters": {"sender": sender, "subject": subject},
            "result_count": len(matches),
        }
    )
    _save("usage_log.json", audit)

    return {
        "user": user,
        "filters": {"sender": sender, "subject": subject},
        "messages": matches,
        "meta": {"count": len(matches), "folders_observed": sorted(folder_counts.keys())},
    }

def send_email(from_user, to, subject, body, content_type="plain", sender_name=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0235000" if __import__("os").path.isdir("./environment_mix/0235000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    t0 = time.time()
    status = "ok"

    # ---- validation ----
    for k, v in [("from_user", from_user), ("to", to), ("subject", subject), ("body", body)]:
        if not isinstance(v, str) or not v.strip():
            status = "validation_error"
            audit = _load("usage_log.json")
            if not isinstance(audit, list):
                audit = []
            audit.append(
                {
                    "id": f"req_{len(audit)+1}",
                    "endpoint": "send_email",
                    "timestamp": _now_iso(),
                    "status": status,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "from_user": from_user if isinstance(from_user, str) else None,
                }
            )
            _save("usage_log.json", audit)
            return _err("VALIDATION_ERROR", f"Missing or empty required field: {k}.")

    if content_type is None:
        content_type = "plain"
    if not isinstance(content_type, str):
        status = "validation_error"
        audit = _load("usage_log.json")
        if not isinstance(audit, list):
            audit = []
        audit.append(
            {
                "id": f"req_{len(audit)+1}",
                "endpoint": "send_email",
                "timestamp": _now_iso(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "from_user": from_user,
            }
        )
        _save("usage_log.json", audit)
        return _err("VALIDATION_ERROR", "content_type must be a string.")
    if content_type not in ("plain", "html"):
        status = "validation_error"
        audit = _load("usage_log.json")
        if not isinstance(audit, list):
            audit = []
        audit.append(
            {
                "id": f"req_{len(audit)+1}",
                "endpoint": "send_email",
                "timestamp": _now_iso(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "from_user": from_user,
            }
        )
        _save("usage_log.json", audit)
        return _err("VALIDATION_ERROR", "Unsupported content_type. Supported: plain, html.", supported=["plain", "html"])

    if sender_name is not None and not isinstance(sender_name, str):
        status = "validation_error"
        audit = _load("usage_log.json")
        if not isinstance(audit, list):
            audit = []
        audit.append(
            {
                "id": f"req_{len(audit)+1}",
                "endpoint": "send_email",
                "timestamp": _now_iso(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "from_user": from_user,
            }
        )
        _save("usage_log.json", audit)
        return _err("VALIDATION_ERROR", "sender_name must be a string when provided.")

    # ---- rate limit (simple, observable) ----
    audit = _load("usage_log.json")
    if not isinstance(audit, list):
        audit = []
    now = datetime.datetime.now(datetime.timezone.utc)
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in audit:
        ts = r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            continue
        if dt >= window_start:
            recent += 1
    if recent >= 60:
        status = "rate_limited"
        audit.append(
            {
                "id": f"req_{len(audit)+1}",
                "endpoint": "send_email",
                "timestamp": _now_iso(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "from_user": from_user,
            }
        )
        _save("usage_log.json", audit)
        return _err("RATE_LIMIT", "Too many requests. Please retry later.", limit=60, window_seconds=60)

    # ---- load mailbox store and locate sender mailbox ----
    mailboxes = _load("mailboxes.json")

    sender_mailbox = None
    sender_container = None  # dict representing mailboxes store if dict-form
    sender_index = None      # index if list-form

    if isinstance(mailboxes, dict):
        sender_container = mailboxes
        sender_mailbox = mailboxes.get(from_user)
    elif isinstance(mailboxes, list):
        for i, row in enumerate(mailboxes):
            if isinstance(row, dict) and row.get("user") == from_user:
                sender_mailbox = row
                sender_index = i
                break
    else:
        mailboxes = []

    if sender_mailbox is None:
        status = "not_found"
        audit.append(
            {
                "id": f"req_{len(audit)+1}",
                "endpoint": "send_email",
                "timestamp": _now_iso(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "from_user": from_user,
            }
        )
        _save("usage_log.json", audit)
        return _err("NOT_FOUND", "from_user mailbox does not exist.", from_user=from_user)

    # Ensure folder lists exist
    if not isinstance(sender_mailbox, dict):
        status = "validation_error"
        audit.append(
            {
                "id": f"req_{len(audit)+1}",
                "endpoint": "send_email",
                "timestamp": _now_iso(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "from_user": from_user,
            }
        )
        _save("usage_log.json", audit)
        return _err("VALIDATION_ERROR", "Mailbox data is invalid.")

    if "Sent" not in sender_mailbox or not isinstance(sender_mailbox.get("Sent"), list):
        sender_mailbox["Sent"] = []

    # Compute next id across all folders in this mailbox (per schema: integer id)
    max_id = 0
    for fld, msgs in sender_mailbox.items():
        if fld == "user":
            continue
        if isinstance(msgs, list):
            for m in msgs:
                if isinstance(m, dict):
                    mid = m.get("id")
                    if isinstance(mid, int) and mid > max_id:
                        max_id = mid
    new_id = max_id + 1

    # Create message as recorded by PostHaven Mailbox Manager schema fields (no extra persistence fields)
    msg = {
        "id": new_id,
        "from": from_user if not (sender_name and sender_name.strip()) else f"{sender_name.strip()} <{from_user}>",
        "to": to,
        "subject": subject,
        "body": body,
        "date": _now_iso(),
        "folder": "Sent",
        "in_reply_to": None,
        "thread_id": f"thr-{from_user}-{new_id}",
        "cc": "",
        "attachments": [],
    }

    sender_mailbox["Sent"].append(msg)

    # Write back mailboxes store
    if isinstance(sender_container, dict):
        sender_container[from_user] = sender_mailbox
        mailboxes_to_save = sender_container
    else:
        # list-form
        if sender_index is not None:
            mailboxes[sender_index] = sender_mailbox
        mailboxes_to_save = mailboxes

    _save("mailboxes.json", mailboxes_to_save)

    status = "ok"
    audit.append(
        {
            "id": f"req_{len(audit)+1}",
            "endpoint": "send_email",
            "timestamp": _now_iso(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "from_user": from_user,
            "to": to,
            "message_id": new_id,
        }
    )
    _save("usage_log.json", audit)

    return {"message": msg}

def clear_folder(user, folder="INBOX", **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0235000" if __import__("os").path.isdir("./environment_mix/0235000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    t0 = time.time()
    status = "ok"

    # ---- validation ----
    if not isinstance(user, str) or not user.strip():
        status = "validation_error"
        audit = _load("usage_log.json")
        if not isinstance(audit, list):
            audit = []
        audit.append(
            {
                "id": f"req_{len(audit)+1}",
                "endpoint": "clear_folder",
                "timestamp": _now_iso(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "user": user if isinstance(user, str) else None,
            }
        )
        _save("usage_log.json", audit)
        return _err("VALIDATION_ERROR", "Missing or empty user email address.")

    if folder is None:
        folder = "INBOX"
    if not isinstance(folder, str) or not folder.strip():
        status = "validation_error"
        audit = _load("usage_log.json")
        if not isinstance(audit, list):
            audit = []
        audit.append(
            {
                "id": f"req_{len(audit)+1}",
                "endpoint": "clear_folder",
                "timestamp": _now_iso(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "user": user,
            }
        )
        _save("usage_log.json", audit)
        return _err("VALIDATION_ERROR", "folder must be a non-empty string.")

    folder = folder.strip()

    # ---- rate limit ----
    audit = _load("usage_log.json")
    if not isinstance(audit, list):
        audit = []
    now = datetime.datetime.now(datetime.timezone.utc)
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in audit:
        ts = r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            continue
        if dt >= window_start:
            recent += 1
    if recent >= 60:
        status = "rate_limited"
        audit.append(
            {
                "id": f"req_{len(audit)+1}",
                "endpoint": "clear_folder",
                "timestamp": _now_iso(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "user": user,
            }
        )
        _save("usage_log.json", audit)
        return _err("RATE_LIMIT", "Too many requests. Please retry later.", limit=60, window_seconds=60)

    # ---- locate mailbox ----
    mailboxes = _load("mailboxes.json")
    mailbox = None
    container = None
    idx = None

    if isinstance(mailboxes, dict):
        container = mailboxes
        mailbox = mailboxes.get(user)
    elif isinstance(mailboxes, list):
        for i, row in enumerate(mailboxes):
            if isinstance(row, dict) and row.get("user") == user:
                mailbox = row
                idx = i
                break

    if mailbox is None:
        status = "not_found"
        audit.append(
            {
                "id": f"req_{len(audit)+1}",
                "endpoint": "clear_folder",
                "timestamp": _now_iso(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "user": user,
                "folder": folder,
            }
        )
        _save("usage_log.json", audit)
        return _err("NOT_FOUND", "Mailbox does not exist for user.", user=user)

    if not isinstance(mailbox, dict) or folder not in mailbox:
        status = "not_found"
        audit.append(
            {
                "id": f"req_{len(audit)+1}",
                "endpoint": "clear_folder",
                "timestamp": _now_iso(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "user": user,
                "folder": folder,
            }
        )
        _save("usage_log.json", audit)
        return _err("NOT_FOUND", "Folder does not exist in mailbox.", user=user, folder=folder)

    if not isinstance(mailbox.get(folder), list):
        status = "validation_error"
        audit.append(
            {
                "id": f"req_{len(audit)+1}",
                "endpoint": "clear_folder",
                "timestamp": _now_iso(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "user": user,
                "folder": folder,
            }
        )
        _save("usage_log.json", audit)
        return _err("VALIDATION_ERROR", "Folder data is invalid; expected a list of messages.", folder=folder)

    cleared_messages = mailbox.get(folder)[:]  # return what was cleared (useful)
    cleared_count = len(cleared_messages)

    mailbox[folder] = []

    # Persist mutation
    if isinstance(container, dict):
        container[user] = mailbox
        _save("mailboxes.json", container)
    else:
        if idx is not None:
            mailboxes[idx] = mailbox
            _save("mailboxes.json", mailboxes)
        else:
            status = "not_found"
            audit.append(
                {
                    "id": f"req_{len(audit)+1}",
                    "endpoint": "clear_folder",
                    "timestamp": _now_iso(),
                    "status": status,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "user": user,
                    "folder": folder,
                }
            )
            _save("usage_log.json", audit)
            return _err("NOT_FOUND", "Mailbox does not exist for user.", user=user)

    status = "ok"
    audit.append(
        {
            "id": f"req_{len(audit)+1}",
            "endpoint": "clear_folder",
            "timestamp": _now_iso(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "user": user,
            "folder": folder,
            "cleared": cleared_count,
        }
    )
    _save("usage_log.json", audit)

    return {"user": user, "folder": folder, "cleared": cleared_count, "messages": cleared_messages}
